def level0_move_left_to_first_corridor(s, a):
    def aid(x):
        try:
            return int(getattr(x, 'value', x))
        except Exception:
            return x
    def grid(obs):
        f = obs.get('frame') if isinstance(obs, dict) else getattr(obs, 'frame', None)
        if f is None:
            return None
        if hasattr(f, 'tolist'):
            f = f.tolist()
        if isinstance(f, (list, tuple)) and f and isinstance(f[0], (list, tuple)):
            first_row = f[0][0] if f[0] else None
            if isinstance(first_row, (list, tuple)) or hasattr(first_row, 'tolist'):
                f = f[0]
        if hasattr(f, 'tolist'):
            f = f.tolist()
        return f if isinstance(f, (list, tuple)) and f else None
    def player_center(obs):
        g = grid(obs)
        if g is None:
            return None
        pts = [(x, y) for y, row in enumerate(g) for x, v in enumerate(row) if int(v) == 12]
        if not pts:
            return None
        return (sum(x for x, _ in pts) / len(pts), sum(y for _, y in pts) / len(pts))
    c = player_center(s)
    if c is not None:
        x, y = c
        return aid(a) == 3 and x > 23 and y >= 40
    full_reset = bool(s.get('full_reset', False)) if isinstance(s, dict) else bool(getattr(s, 'full_reset', False))
    return full_reset and aid(a) == 3

