        pts = [(x, y) for y, row in enumerate(g) for x, v in enumerate(row) if int(v) == 12]
        if not pts:
            return None, None
        xs = [x for x, _ in pts]
        ys = [y for _, y in pts]
        return g, (min(xs), min(ys), max(xs), max(ys))
    g, box = player_box(s)
    if g is None or box is None:
        return False
    dx, dy = {1: (0, -5), 2: (0, 5), 3: (-5, 0), 4: (5, 0)}.get(aid(a), (0, 0))
    x0, y0, x1, y1 = box
    h = len(g)
    w = len(g[0]) if h else 0
    nx0, ny0, nx1, ny1 = x0 + dx, y0 + dy, x1 + dx, y1 + dy + 3
