    dx, dy = {1: (0, -5), 2: (0, 5), 3: (-5, 0), 4: (5, 0)}.get(aid(a), (0, 0))
    return py > sy and abs(px + dx - sx) <= 3.5 and abs(py + dy - sy) <= 3.5

def matched_action_avoids_extra_rotation_switch(s, a):
    def aid(x):
        try:
            return int(getattr(x, 'value', x))
        except Exception:
            return x
    def grid(obs):
        f = obs.get('frame') if isinstance(obs, dict) else getattr(obs, 'frame', None)
        if f is None:
            return None
        if hasattr(f, 'tolist'):
            f = f.tolist()
        if isinstance(f, (list, tuple)) and f and isinstance(f[0], (list, tuple)):
            first_row = f[0][0] if f[0] else None
            if isinstance(first_row, (list, tuple)) or hasattr(first_row, 'tolist'):
                f = f[0]
        if hasattr(f, 'tolist'):
            f = f.tolist()
        return f if isinstance(f, (list, tuple)) and f else None
    def shape_matches(obs):
        g = grid(obs)
        if g is None:
            return None
        def pat(region):
            x0, y0, x1, y1 = region
            pts = [(x, y) for y in range(y0, min(len(g), y1 + 1)) for x in range(x0, min(len(g[y]), x1 + 1)) if int(g[y][x]) == 9]
            if not pts:
                return None
            xs = [x for x, _ in pts]
            ys = [y for _, y in pts]
            bx0, by0, bx1, by1 = min(xs), min(ys), max(xs), max(ys)
            out = []
            for gy in range(3):
                row_out = []
                for gx in range(3):
                    cx0 = bx0 + int(gx * (bx1 - bx0 + 1) / 3)
                    cx1 = bx0 + int((gx + 1) * (bx1 - bx0 + 1) / 3) - 1
                    cy0 = by0 + int(gy * (by1 - by0 + 1) / 3)
                    cy1 = by0 + int((gy + 1) * (by1 - by0 + 1) / 3) - 1
                    row_out.append(1 if any(0 <= yy < len(g) and 0 <= xx < len(g[yy]) and int(g[yy][xx]) == 9 for yy in range(cy0, max(cy0, cy1) + 1) for xx in range(cx0, max(cx0, cx1) + 1)) else 0)
                out.append(tuple(row_out))
            return tuple(out)
        cur = pat((0, 52, 12, 63))
        ref = pat((30, 8, 42, 16))
        return cur is not None and ref is not None and cur == ref
    g = grid(s)
    if g is None or not shape_matches(s):
        return False
    player = [(x, y) for y, row in enumerate(g) for x, v in enumerate(row) if int(v) == 12]
    switch = [(x, y) for y, row in enumerate(g) for x, v in enumerate(row) if int(v) == 1]
    if not player or not switch:
        return True
    px = sum(x for x, _ in player) / len(player)
    py = sum(y for _, y in player) / len(player)
    sx = sum(x for x, _ in switch) / len(switch)
    sy = sum(y for _, y in switch) / len(switch)
    dx, dy = {1: (0, -5), 2: (0, 5), 3: (-5, 0), 4: (5, 0)}.get(aid(a), (0, 0))
    before = abs(px - sx) + abs(py - sy)
    after = abs(px + dx - sx) + abs(py + dy - sy)
    return after >= before

def player_is_above_rotation_switch(s, a):
    del a
    if isinstance(s, dict):
        player = s.get('player')
        switch = s.get('rotation_switch')
        if player and switch:
            return float(player['center'][1]) < float(switch['center'][1])
    return False

def player_is_aligned_with_rotation_switch_column(s, a):
    del a
    if not isinstance(s, dict):
        return False
    player = s.get('player')
    switch = s.get('rotation_switch')
    if not player or not switch:
        return False
    px = float(player['center'][0])
    sx = float(switch['center'][0])
    player_half_width = float(player['width']) / 2.0
    switch_half_width = float(switch['width']) / 2.0
    return abs(px - sx) <= max(player_half_width, switch_half_width)
